import uuid
from datetime import date

from pydantic import BaseModel, ConfigDict, Field, HttpUrl, model_validator

from career_copilot.vault.dates import check_date_range


class Project(BaseModel):
    """Project data sent by the client; the id is generated by the server."""

    name: str = Field(min_length=1)
    description: str | None = Field(default=None, max_length=500)
    url: HttpUrl | None = None
    start_date: date | None = None
    end_date: date | None = None

    # Runs after field validation, so both dates are already `date` objects.
    @model_validator(mode="after")
    def check_end_date_not_before_start_date(self) -> "Project":
        """Reject an end date that is before the start date, when both are given."""
        check_date_range(self.start_date, self.end_date)
        return self


class ProjectRead(Project):
    """Project returned by the API, including its id."""

    # Allows building from ORM objects: ProjectRead.model_validate(project_orm).
    model_config = ConfigDict(from_attributes=True)

    id: uuid.UUID
